	@Test
	void cachedEquivalentQueriesRebindEveryOccurrenceToTheCurrentCallerSources() {
		for (boolean union : List.of(false, true)) {
			AtomicInteger previousLeft = new AtomicInteger();
			AtomicInteger previousRight = new AtomicInteger();
			AtomicInteger currentLeft = new AtomicInteger();
			AtomicInteger currentRight = new AtomicInteger();
			TupleExpr previous = countedPair(previousLeft, previousRight, union);
			TupleExpr current = countedPair(currentLeft, currentRight, union);
			assertEquals(previous, current, "caller identity must not change logical algebra equality");
			PackedPlanCache cache = new PackedPlanCache(8, 1);
			PackedPlanningResult first = PackedCascadesPlanner.optimize(previous, OptimizationGoal.root(), cache,
					CACHE_CONTEXT, COSTS);
			PackedPlanningResult second = PackedCascadesPlanner.optimize(current, OptimizationGoal.root(), cache,
					CACHE_CONTEXT, COSTS);
			assertFalse(first.metrics().planCacheHit());
			assertTrue(second.metrics().planCacheHit(), "occurrence structure remains reusable across callers");
			List<String> expected = union ? List.of("u=\"1\"", "u=\"1\"") : List.of("u=\"1\"");
			assertPreparedMutableEvaluation(second.selectedPlan(), expected,
					List.of(currentLeft, currentRight), List.of(previousLeft, previousRight));
			assertPreparedMutableEvaluation(first.selectedPlan(), expected,
					List.of(previousLeft, previousRight), List.of(currentLeft, currentRight));
			PackedPlanningResult reestimated = PackedCascadesPlanner.optimize(current, OptimizationGoal.root(), cache,
					new PackedPlanCache.Context(1, 2, 3, 4, 5, 99, 7), COSTS);
			assertFalse(reestimated.metrics().planCacheHit());
			assertTrue(reestimated.metrics().queryTemplateCacheHit(), "cost-provider changes reuse the query template");
			assertPreparedMutableEvaluation(reestimated.selectedPlan(), expected,
					List.of(currentLeft, currentRight), List.of(previousLeft, previousRight));
			List<Iterable<BindingSet>> originalRows = assignmentSources(current);
			List<Iterable<BindingSet>> selectedRows = assignmentSources(second.selectedPlan());
			assertEquals(2, selectedRows.size());
			for (int ordinal = 0; ordinal < originalRows.size(); ordinal++) {
				assertSame(originalRows.get(ordinal), selectedRows.get(ordinal));
			}
		}
	}

	private static TupleExpr countedPair(AtomicInteger left, AtomicInteger right, boolean union) {
		Filter first = new Filter(countedMutableValues(left, "1"), new Bound(Var.of("u")));
		Filter second = new Filter(countedMutableValues(right, "1"), new Bound(Var.of("u")));
		return union ? new Union(first, second) : new Join(first, second);
	}

	private static List<Iterable<BindingSet>> assignmentSources(TupleExpr source) {
		List<Iterable<BindingSet>> sources = new ArrayList<>();
		source.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(BindingSetAssignment assignment) {
				sources.add(assignment.getBindingSets());
			}
		});
		return sources;
	}

	@Test
	void repeatedEffectfulWrappersRetainTheirOriginalInvocationCounts() {
		AtomicInteger callbacks = new AtomicInteger();
		Function effect = new Function() {
			@Override
			public String getURI() {
				return "urn:test:packed-repeated-effect-occurrence";
			}

			@Override
			public Value evaluate(ValueFactory factory, Value... arguments) {
				callbacks.incrementAndGet();
				return factory.createLiteral("fixed");
			}

			@Override
			public boolean mustReturnDifferentResult() {
				return true;
			}
		};
		FunctionRegistry.getInstance().add(effect);
		try {
			BindingSetAssignment seed = new BindingSetAssignment();
			seed.setDeclaredBindingNames(Set.of("seed"));
			seed.setBindingSets(List.of(new ListBindingSet(List.of("seed"), VF.createLiteral("one"))));
			Extension left = new Extension(seed,
					new ExtensionElem(new FunctionCall(effect.getURI(), Var.of("seed")), "effect"));
			TupleExpr source = new Join(left, left.clone());
			PackedQuery encoded = PackedQueryCodec.encode(source);
			List<Integer> wrapperOccurrences = new ArrayList<>();
			for (int id = 1; id <= encoded.relationCount(); id++) {
				if (encoded.relOperator(id) == PackedRelOp.EXTENSION) {
					wrapperOccurrences.add(encoded.relOccurrence(id));
				}
			}
			assertEquals(2, wrapperOccurrences.size(), "an effectful wrapper is an evaluation occurrence");
			assertNotEquals(0, wrapperOccurrences.get(0).intValue());
			assertNotEquals(wrapperOccurrences.get(0), wrapperOccurrences.get(1));
			List<String> expected = List.of("effect=\"fixed\"|seed=\"one\"");
			assertEquals(expected, evaluate(source, null, () -> callbacks.set(0)));
			assertEquals(2, callbacks.get());
			assertCountedMutableRoutes(source, expected, List.of(callbacks), List.of(2));
		} finally {
			FunctionRegistry.getInstance().remove(effect);
		}
	}

