	private static void assertPreparedMutableRoutes(TupleExpr source, List<String> expected,
			List<AtomicInteger> callerSources) {
		assertAll(countedRoutes(source).stream()
				.map(route -> (Executable) () -> assertPreparedMutableEvaluation(route.get(), expected, callerSources,
						List.of())));
	}

	/** Mutable VALUES are captured during entry preparation; execution must read only that prepared snapshot. */
	private static void assertPreparedMutableEvaluation(TupleExpr source, List<String> expected,
			List<AtomicInteger> callerSources, List<AtomicInteger> unrelatedSources) {
		assertEquals(expected, evaluatePreparedMutable(source, callerSources, unrelatedSources));
	}

	private static List<String> evaluatePreparedMutable(TupleExpr source, List<AtomicInteger> callerSources,
			List<AtomicInteger> unrelatedSources) {
		callerSources.forEach(counter -> counter.set(0));
		unrelatedSources.forEach(counter -> counter.set(0));
		List<String> actual = evaluate(source, null, () -> {
			for (AtomicInteger counter : callerSources) {
				assertTrue(counter.get() > 0, "preparation must capture each actual caller source");
			}
			for (AtomicInteger counter : unrelatedSources) {
				assertEquals(0, counter.get(), "preparation cannot borrow another caller's source");
			}
			callerSources.forEach(counter -> counter.set(0));
			unrelatedSources.forEach(counter -> counter.set(0));
		});
		for (AtomicInteger counter : callerSources) {
			assertEquals(0, counter.get(), "execution must not reopen the mutable caller source");
		}
		for (AtomicInteger counter : unrelatedSources) {
			assertEquals(0, counter.get(), "execution must not borrow another caller's source");
		}
		return actual;
	}

	private static BindingSetAssignment countedMutableValues(AtomicInteger opens, String... values) {
		return countedMutableNamedValues(opens, "u", List.of(values));
	}

	private static BindingSetAssignment countedMutableNamedValues(AtomicInteger opens, String name,
			List<String> values) {
		List<BindingSet> rows = new ArrayList<>() {
			@Override
			public Iterator<BindingSet> iterator() {
				opens.incrementAndGet();
				return super.iterator();
			}
		};
		for (String value : values) {
			MapBindingSet row = new MapBindingSet();
			row.addBinding(name, VF.createLiteral(value));
			rows.add(row);
		}
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setDeclaredBindingNames(Set.of(name));
		assignment.setBindingSets(rows);
		return assignment;
	}

	private static void assertCountedMutableRoutes(TupleExpr source, List<String> expected,
			List<AtomicInteger> counters) {
		assertCountedMutableRoutes(source, expected, counters, counters.stream().map(counter -> 1).toList());
	}

	private static List<Supplier<TupleExpr>> countedRoutes(TupleExpr source) {
		List<Supplier<TupleExpr>> routes = new ArrayList<>();
		routes.add(() -> materialized(PackedQueryCodec.encode(source)));
		routes.add(() -> materialized(PackedQueryCodec.encodeForPlanning(source)));
		routes.add(() -> materialized(PackedQueryCodec.encodeForParameterizedPlanning(source, null)));
		for (OptimizationGoal goal : goals()) {
			routes.add(() -> PackedCascadesPlanner.optimize(source, goal, COSTS).selectedPlan());
		}
		PackedPlanCache cache = new PackedPlanCache(8, 1);
		routes.add(() -> PackedCascadesPlanner.optimize(source, OptimizationGoal.root(), cache, CACHE_CONTEXT, COSTS)
				.selectedPlan());
		routes.add(() -> PackedCascadesPlanner.optimize(source, OptimizationGoal.root(), cache, CACHE_CONTEXT, COSTS)
				.selectedPlan());
		return routes;
	}

	private static void assertCountedMutableRoutes(TupleExpr source, List<String> expected,
			List<AtomicInteger> counters, List<Integer> expectedCounts) {
		List<Supplier<TupleExpr>> routes = countedRoutes(source);
		assertAll(routes.stream().map(route -> (Executable) () -> {
			TupleExpr plan = route.get();
			assertEquals(expected, evaluate(plan, null, () -> counters.forEach(counter -> counter.set(0))),
					plan::toString);
			for (int ordinal = 0; ordinal < counters.size(); ordinal++) {
				int occurrence = ordinal;
				assertEquals(expectedCounts.get(ordinal).intValue(), counters.get(ordinal).get(),
						() -> "route=" + routes.indexOf(route) + ", source occurrence=" + occurrence + "\n" + plan);
			}
		}));
	}

	private static TupleExpr materialized(PackedQuery query) {
		return PackedPlanMaterializer.materialize(query, query.rootRelId());
	}

	@Test
	void nullableOriginalProviderAndLaterProducerPreserveTheObservedInputFrame() {
		for (boolean laterProducer : List.of(false, true)) {
			BindingSetAssignment left = new BindingSetAssignment();
			left.setDeclaredBindingNames(Set.of("u"));
			left.setBindingSets(List.of(new ListBindingSet(List.of("u"), VF.createLiteral("one")),
					new ListBindingSet(List.of("u"), VF.createLiteral("two"))));
			BindingSetAssignment right = new BindingSetAssignment();
			right.setDeclaredBindingNames(Set.of("u", "x"));
			right.setBindingSets(List.of(new ListBindingSet(List.of("u", "x"),
					VF.createLiteral("one"), VF.createLiteral("early"))));
			Extension reader = new Extension(new SingletonSet(), new ExtensionElem(
					new Coalesce(List.of(Var.of("x"), new ValueConstant(VF.createLiteral("missing")))), "seen"));
			TupleExpr source = new Join(new LeftJoin(left, right), reader);
			if (laterProducer) {
				source = new Join(source, new Extension(new SingletonSet(),
						new ExtensionElem(new ValueConstant(VF.createLiteral("late")), "x")));
			}
			List<String> expected = laterProducer
					? List.of("seen=\"early\"|u=\"one\"|x=\"late\"", "seen=\"missing\"|u=\"two\"|x=\"late\"")
					: List.of("seen=\"early\"|u=\"one\"|x=\"early\"", "seen=\"missing\"|u=\"two\"");
			assertEquals(expected, evaluate(source, null));
			assertPackedRoutes(source, expected);
		}
	}

	@Test
	void parsedValuesKeepAuditedOwnershipAndBothContextualLookupDirections() {
		TupleExpr source = PackedPlanDifferentialSupport.parse("""
				SELECT * WHERE { ?obs <urn:medical-value> ?value . VALUES ?value { 50 60 70 } }
				""");
		boolean[] directions = new boolean[2];
		PackedCostModel costs = new PackedCostModel() {
			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				return query.isBindingSetAssignment(relationId) ? query.bindingAssignmentRowCount(relationId) : 900.0d;
			}

			@Override
			public void estimate(PackedQueryView query, int relationId, PackedCostContext context,
					PackedCostEstimate output) {
				if (query.isStatementPattern(relationId)
						&& query.prefixBindsStatementComponent(context, relationId, 2)) {
					directions[0] = true;
					output.setContextualRows(3.0d, 3.0d);
				} else if (query.isBindingSetAssignment(relationId) && context.prefixRelationCount() > 0
						&& query.isStatementPattern(context.prefixRelationId(context.prefixRelationCount() - 1))) {
					directions[1] = true;
					output.setContextualRows(900.0d, 900.0d);
				} else {
					double rows = estimateRows(query, relationId);
					output.setRows(rows, rows);
				}
			}
		};
		PackedQuery encoded = PackedQueryCodec.encode(source);
		for (int id = 1; id <= encoded.relationCount(); id++) {
			if (encoded.relOperator(id) == PackedRelOp.BINDING_SET_ASSIGNMENT) {
				assertTrue(encoded.relationReplayIsSafe(id),
						"parser-owned immutable VALUES retain audited replay proof");
			}
		}
		PackedCascadesPlanner.optimize(source, OptimizationGoal.root(), costs);
		assertTrue(directions[0], "VALUES-to-pattern access must remain costed for genuine parser-owned rows");
		assertTrue(directions[1], "pattern-to-VALUES access must remain costed for genuine parser-owned rows");
	}

	@Test
	void internallySuppliedFiltersKeepPackedSearchAndCacheReuseAcrossAllEntryRoutes() {
		Filter parameterized = parameterized(values("x", "1", "2"));
		TupleExpr source = new Join(values("u", "1", "2", "2"), parameterized);
		List<String> expected = List.of("u=\"1\"|x=\"1\"", "u=\"2\"|x=\"2\"", "u=\"2\"|x=\"2\"");
		assertEquals(expected, evaluate(source, null));
		Filter independent = parameterized.clone();
		independent.setRequiredInputBindingNames(Set.of());
		TupleExpr differentFrame = new Join(values("u", "1", "2", "2"), independent);
		assertEquals(source, differentFrame, "logical equality deliberately excludes physical input facts");

		assertAll(
				() -> assertNotNull(PackedQueryCacheIdentity.createComplete(source)),
				() -> assertNotNull(PackedQueryCacheIdentity.createPlanIdentity(source)),
				() -> assertNotNull(PackedQueryFamilyIdentity.create(source, null)),
				() -> assertPackedRoutes(source, expected));
		assertNotEquals(PackedQueryCacheIdentity.createComplete(source),
				PackedQueryCacheIdentity.createComplete(differentFrame),
				"parameterized and independent RHS gates cannot reuse different executable semantics");
		assertFalse(PackedQueryCacheIdentity.createComplete(source)
				.matches(PackedQueryCacheIdentity.createComplete(differentFrame)));
		assertEquals(Set.of("u"), parameterized.getRequiredInputBindingNames(),
				"planning owns its normalization clone");
	}

