	@Test
	void preparationAuditsSharedDescendantsOnceAndCodecScanWorkDoesNotGrowWithPureWrapperDepth() {
		int shallowCodecScans = 0;
		for (int depth : List.of(8, 64)) {
			AtomicInteger rowScans = new AtomicInteger();
			List<BindingSet> immutableRows = List.of(new ListBindingSet(List.of("u"), VF.createLiteral("one")));
			BindingSetAssignment assignment = new BindingSetAssignment();
			assignment.setDeclaredBindingNames(Set.of("u"));
			assignment.setBindingSets(new AbstractList<BindingSet>() {
				@Override
				public BindingSet get(int index) {
					return immutableRows.get(index);
				}

				@Override
				public int size() {
					return immutableRows.size();
				}

				@Override
				public Iterator<BindingSet> iterator() {
					rowScans.incrementAndGet();
					return super.iterator();
				}
			});
			TupleExpr source = assignment;
			for (int ordinal = 0; ordinal < depth; ordinal++) {
				source = new Filter(source, new Bound(Var.of("u")));
			}
			rowScans.set(0);
			PackedInputFrameNormalizer.Prepared prepared = PackedInputFrameNormalizer.prepare(source,
					node -> new UnsupportedCascadesOperatorException(node.getClass(), "test.requiredInputFrame"));
			assertEquals(depth + 1, prepared.replaySafety().size(), "the audit covers every tuple node");
			assertEquals(1, rowScans.get(), "an invocation-local proof audits the shared VALUES descendant once");
			rowScans.set(0);
			PackedQuery encoded = PackedQueryCodec.encodeForPlanning(source);
			assertTrue(encoded.relationCount() >= depth + 1);
			assertTrue(rowScans.get() > 0, "Hit Proof: this codec route reaches the audited VALUES source");
			if (depth == 8) {
				shallowCodecScans = rowScans.get();
			} else {
				assertEquals(shallowCodecScans, rowScans.get(),
						"pure wrapper depth does not rescan a shared descendant during preparation");
			}
		}
	}

